{
  "name": "find_table_entry",
  "confidence": "high",
  "docstring": "Scans a fixed-size global table for the highest-priority record whose length-prefixed name matches the supplied key and returns a pointer to that record's data field.",
  "subsystem": "libmisc",
  "var_renames": {
    "a1": "key_len_prefixed_name",
    "v1": "table_entry",
    "v3": "best_entry",
    "v4": "table_end",
    "v5": "best_priority",
    "v6": "key_data",
    "v7": "entry_name_len"
  },
  "struct_hints": [
    {
      "offset": 8,
      "meaning": "entry data pointer or active-record marker (also the returned payload address)"
    },
    {
      "offset": 16,
      "meaning": "length of the entry's name"
    },
    {
      "offset": 17,
      "meaning": "name bytes of the entry"
    },
    {
      "offset": 64,
      "meaning": "signed priority byte used to choose the best matching entry"
    }
  ]
}
